import re
from datetime import datetime

_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_MANUAL = "manual"


def _text(row, key):
    value = row.get(key)
    return "" if value is None else str(value)


def _normalize_email(raw):
    s = raw.strip()
    m = re.search(r"<([^<>]*)>", s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            domain = "gmail.com"
        s = f"{local}@{domain}"
    return s


def _is_valid_email(email):
    if email.count("@") != 1:
        return False
    local, domain = email.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    """Return the 10-digit phone number, or "" if it is not valid."""
    s = raw.lower()
    cut = len(s)
    for marker in ("x", "ext", "#"):
        pos = s.find(marker)
        if pos != -1:
            cut = min(cut, pos)
    digits = "".join(c for c in s[:cut] if c in "0123456789")
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _normalize_zip(raw):
    z = raw.strip()
    m = re.fullmatch(r"([0-9]{4,5})-[0-9]{4}", z)  # ZIP+4; 4-digit prefix = Excel dropped the leading 0
    if m:
        z = m.group(1)
    if re.fullmatch(r"[0-9]{4}", z):
        z = "0" + z
    if re.fullmatch(r"[0-9]{5}", z):
        return z
    return ""


def _normalize_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    return datetime.min  # unparseable: treat as oldest


def dedupe_contacts(rows):
    # Step 1: normalize each row, dropping rows with no valid email or phone.
    records = []
    for index, row in enumerate(rows):
        email = _normalize_email(_text(row, "email"))
        if not _is_valid_email(email):
            email = ""
        phone = _normalize_phone(_text(row, "phone"))
        if not email and not phone:
            continue
        source = _text(row, "source").strip().lower()
        records.append({
            "index": index,
            "first": _normalize_name(_text(row, "first_name")),
            "last": _normalize_name(_text(row, "last_name")),
            "zip": _normalize_zip(_text(row, "zip")),
            "email": email,
            "phone": phone,
            "source": source,
            "manual": source == _MANUAL,
            "updated": _parse_updated(_text(row, "updated")),
            "opted_out": _text(row, "opted_out").strip().lower() in _OPT_OUT_VALUES,
            "tags": {
                t.strip().lower()
                for t in re.split(r"[;,]", _text(row, "tags"))
                if t.strip()
            },
        })

    # Step 2: union-find so matches are transitive.
    parent = list(range(len(records)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    first_by_email = {}
    first_by_phone_last = {}
    for pos, rec in enumerate(records):
        if rec["email"]:
            key = rec["email"]
            if key in first_by_email:
                union(pos, first_by_email[key])
            else:
                first_by_email[key] = pos
        if rec["phone"] and rec["last"]:
            key = (rec["phone"], rec["last"].lower())
            if key in first_by_phone_last:
                union(pos, first_by_phone_last[key])
            else:
                first_by_phone_last[key] = pos

    # Group rows; dict insertion order follows each group's earliest row.
    groups = {}
    for pos in range(len(records)):
        groups.setdefault(find(pos), []).append(records[pos])

    # Step 3: pick one value per field per group and build output.
    def pick(group, field):
        candidates = [r for r in group if r[field]]
        if not candidates:
            return ""
        best = max(
            candidates,
            key=lambda r: (r["manual"], r["updated"], -r["index"]),
        )
        return best[field]

    result = []
    for group in groups.values():
        latest = max(r["updated"] for r in group)
        result.append({
            "first_name": pick(group, "first"),
            "last_name": pick(group, "last"),
            "zip": pick(group, "zip"),
            "email": pick(group, "email"),
            "phone": pick(group, "phone"),
            "source": pick(group, "source"),
            "tags": ";".join(sorted(set().union(*(r["tags"] for r in group)))),
            "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
            "updated": f"{latest.year:04d}-{latest.month:02d}-{latest.day:02d}",
        })
    return result
```

Notes:

- **Opted-out contacts are still returned.** Per the rules, a person who opted out in any row gets `opted_out: "Y"`, but the function doesn't remove them. Filter out `opted_out == "Y"` before building the send list.
- **Unparseable `updated` values** are treated as the oldest possible date. The rules say every value is in one of the three formats, so this should never trigger, but it avoids a crash if one isn't.
- **ZIP+4 handling** also accepts a 4-digit prefix (for example, `2139-4307`), since that's what Excel leaves after dropping the leading zero.
- **Name casing** follows the rules as written, so `O'BRIEN` becomes `O'Brien` via `str.title()`. Check any all-caps names you care about.
